<?php if($u['role']==='seeker'):$offers=query('SELECT i.*,j.title,j.company FROM hiring_invitations i JOIN eprofile j ON j.id=i.job_id WHERE i.seeker_id=? ORDER BY i.id DESC',[$u['id']]);?><h2>Your hiring offers</h2><?php $found=false;foreach($offers as $offer):$found=true;?><article class="application"><h3><?=h($offer['title'])?> · <?=h($offer['company'])?></h3><p><?=h($offer['status'])?></p><a class="text-link" href="job.php?id=<?=h($offer['job_id'])?>">View job ↗</a><?php if($offer['status']==='Offered'):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="offer-response"><input type="hidden" name="invitation_id" value="<?=h($offer['id'])?>"><button class="button" name="status" value="Accepted">Accept offer</button> <button class="button secondary" name="status" value="Declined">Decline</button></form><?php endif;?></article><?php endforeach;if(!$found):?><p class="empty">Offers from employers will appear here.</p><?php endif;endif;?>
